def conv_params(c_in, c_out, k, bias=False, groups=1):
    """Learnable parameters of a k x k convolution."""
    return (c_in // groups) * c_out * k * k + (c_out if bias else 0)


def bn_params(c):
    """Learnable BatchNorm parameters: gamma and beta. (Running mean/var are buffers, not parameters.)"""
    return 2 * c


def basic_block_params(c_in, c_out, project=False, with_bn=True):
    """3x3 -> 3x3. `project` adds a 1x1 conv (+BN) on the shortcut, needed when channels or stride change."""
    n = conv_params(c_in, c_out, 3) + conv_params(c_out, c_out, 3)
    if with_bn:
        n += 2 * bn_params(c_out)
    if project:
        n += conv_params(c_in, c_out, 1) + (bn_params(c_out) if with_bn else 0)
    return n


def bottleneck_params(c_in, c_mid, c_out, project=False, with_bn=True):
    """1x1 reduce -> 3x3 -> 1x1 expand."""
    n = conv_params(c_in, c_mid, 1) + conv_params(c_mid, c_mid, 3) + conv_params(c_mid, c_out, 1)
    if with_bn:
        n += 2 * bn_params(c_mid) + bn_params(c_out)
    if project:
        n += conv_params(c_in, c_out, 1) + (bn_params(c_out) if with_bn else 0)
    return n
